# --kde on a home whose ~/.config/kcminputrc and ~/.config/kxkbrc Plasma already wrote: the keys in home/.config/kcminputrc
# (keyboard repeat) and home/.config/kxkbrc (no XKB options) are merged in, and the others are left alone.
IMAGE=steamos
ARGS="--variant steamos --kde"
FILES=".config/kcminputrc .config/kxkbrc"
